-- GeoNames cities15000 snapshot, downloaded 2026-10-21. CC BY 4.0.
-- https://www.geonames.org/export/ ; https://creativecommons.org/licenses/by/4.0/
begin;
create table public.matchmaking_cities (
  id integer primary key, name text not null, search_name text not null,
  region text not null, country text not null,
  latitude double precision not null check (latitude between -90 and 90),
  longitude double precision not null check (longitude between -180 and 180),
  population bigint not null
);
alter table public.matchmaking_cities enable row level security;
revoke all on public.matchmaking_cities from public, anon, authenticated;
grant select on public.matchmaking_cities to authenticated;
grant all on public.matchmaking_cities to service_role;
create policy "Members can search the city catalog" on public.matchmaking_cities for select to authenticated using (true);
create index matchmaking_city_search on public.matchmaking_cities (search_name text_pattern_ops);
create index matchmaking_city_name on public.matchmaking_cities (lower(name) text_pattern_ops);

create function public.search_matchmaking_cities(query text)
returns table (id integer, name text, region text, country text)
language sql stable set search_path = '' as $$
  select c.id, c.name, c.region, c.country from public.matchmaking_cities c
  where char_length(btrim(query)) between 2 and 80
    and (c.search_name like lower(btrim(query)) || '%' or lower(c.name) like lower(btrim(query)) || '%')
  order by c.population desc, c.id limit 12;
$$;
revoke all on function public.search_matchmaking_cities(text) from public, anon, authenticated;
grant execute on function public.search_matchmaking_cities(text) to authenticated;
commit;
